struct AuditedPayments: Payments {
    let inner: any Payments
    let sink: AuditSink

    func pay(_ p: Payment) async throws -> Receipt {
        sink.record(Subject.current, "pay", p.id, "attempt")
        do { let r = try await inner.pay(p); sink.record(Subject.current, "pay", p.id, "ok"); return r }
        catch { sink.record(Subject.current, "pay", p.id, "failed"); throw error }
    }
}
